unsafe fn addColorBits(
    mut out: *mut c_uchar,
    mut index: size_t,
    mut bits: c_uint,
    mut in_0: c_uint,
) {
    let m: c_uint = if bits == 1 as c_uint {
        7 as c_uint
    } else if bits == 2 as c_uint {
        3 as c_uint
    } else {
        1 as c_uint
    };
    let p: c_uint = (index & m as size_t) as c_uint;
    let byte_index = index.wrapping_mul(bits as size_t).wrapping_div(8 as size_t);
    in_0 &= ((1 as c_uint) << bits).wrapping_sub(1 as c_uint);
    in_0 <<= bits.wrapping_mul(m.wrapping_sub(p));
    let ptr = out.offset(byte_index as isize);
    if p == 0 as c_uint {
        // SAFETY: caller upholds that `out` is valid for writes at the computed byte offset.
        *ptr = in_0 as c_uchar;
    } else {
        // SAFETY: caller upholds that `out` is valid for reads/writes at the computed byte offset.
        *ptr = (*ptr as c_uint | in_0) as c_uchar;
    };
}

